def transform(grid):
    """Mark each divider-separated panel having the greatest marker count."""
    height, width = len(grid), len(grid[0])
    # Identify separator value from complete uniform separator lines. Zero is
    # typical, but this also handles the demo's color-9 dividers.
    separator_values = Counter()
    for row in grid:
        if len(set(row)) == 1:
            separator_values[row[0]] += 1
    for c in range(width):
        col = [grid[r][c] for r in range(height)]
        if len(set(col)) == 1:
            separator_values[col[0]] += 1
    separator = separator_values.most_common(1)[0][0] if separator_values else 0

    def bands_from_lines(lines):
        bands, start = [], 0
        for i, line in enumerate(lines):
            if all(value == separator for value in line):
                if start < i:
                    bands.append((start, i))
                start = i + 1
        if start < len(lines):
            bands.append((start, len(lines)))
        return bands

    row_bands = bands_from_lines(grid)
    col_bands = bands_from_lines([[grid[r][c] for r in range(height)]
                                  for c in range(width)])
    # The marker is the least frequent non-separator color in the cells, while
    # the other color(s) form the panel background.
    color_counts = Counter(v for row in grid for v in row if v != separator)
    marker = min(color_counts, key=color_counts.get)
    counts = [[sum(grid[r][c] == marker
                   for r in range(r0, r1)
