def transform(grid):
    """Split a colored grid into panels and flag panels with exceptional marks."""
    h, w = len(grid), len(grid[0])
    # A separator is a uniform full row/column; select most frequent color
    # among such lines (0 in the test, 9 in the demonstration).
    sep_counts = Counter()
    for row in grid:
        if len(set(row)) == 1:
            sep_counts[row[0]] += 1
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            sep_counts[col[0]] += 1
    sep = sep_counts.most_common(1)[0][0]

    def bands(lines):
        result, start = [], 0
        for i, line in enumerate(lines):
            if all(v == sep for v in line):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < len(lines):
            result.append((start, len(lines)))
        return result

    rb = bands(grid)
    cb = bands([[grid[r][c] for r in range(h)] for c in range(w)])
    colors = Counter(v for row in grid for v in row if v != sep)
    marker = min(colors, key=colors.get)
    panel_counts = [[sum(grid[r][c] == marker
                         for r in range(r0, r1)
                         for c in range(c0, c1))
                    for c0, c1 in cb] for r0, r1 in rb]
    freq = Counter(v for row in panel_counts for v in row)
    # The exceptional value is the least frequent panel count (the demo has
    # one 2-mark panel among otherwise 1-mark panels).
    rare = min(freq, key=freq.get)
    return [[int(v == rare) for v in row] for row in panel_counts]
